/**
 * Portraits: the picture of a sage's own podcast episode, cut to his head and shoulders (lib/portraits.ts,
 * public/data-portraits.json, public/portraits/, assets/og/portraits/, all generated by scripts/build_portraits.py
 * from data/portraits-review.json). Keyed by sage id, and ids are exactly what drifts between data sets (see
 * CLAUDE.md), so every entry carries the roster label it was made for and these tests fail when an id now belongs to a
 * different sage, when a file is missing, stray, too big or the wrong size, when the data file and the review disagree,
 * and when a photograph could reach the site under the illustration caption.
 *
 * The rules are one function over a root directory laid out like the repo (portraitProblems). It runs on the real tree
 * and, in the same file, on a temporary tree made from files of the real set and a small review, each rule shown to fire
 * on a deliberately broken copy. The pictures are read by hand (a WebP header, a JPEG start-of-frame marker): no image
 * library. Nothing here names a sage id of the real set.
 */
import assert from 'node:assert/strict'
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import { getAllSages } from '../lib/serverData'
import {
  PORTRAIT_CREDIT,
  PORTRAIT_SIZE,
  PORTRAIT_SIZE_SM,
  hasPortrait,
  portraitAlt,
  portraitCredit,
  portraitEntries,
  portraitEpisodeHref,
  portraitOf,
} from '../lib/portraits'
import type { Locale } from '../lib/types'

let passed = 0
let failed = 0
let skipped = 0
function test(name: string, fn: () => void) {
  try {
    fn()
    console.log(`  ok  ${name}`)
    passed++
  } catch (e) {
    console.log(`  FAIL ${name}`)
    console.log(`       ${(e as Error).message}`)
    failed++
  }
}

// ---- the limits (mirrors scripts/build_portraits.py, which builds below them) ----
const MAX_LARGE = 40 * 1024
const MAX_SMALL = 8 * 1024
const MAX_OG = 30 * 1024
const MAX_TOTAL = 20 * 1024 * 1024
const OG_SIZE = 320
const PIC = 640
const MIN_CROP = 160
const REASONS = ['photo', 'other-person', 'symbol', 'text', 'gender', 'quality', 'no-episode', 'title-mismatch']
const KINDS = ['illustration', 'photo']
const TOP_KEYS = ['_about', '_approved_photos', 'portraits', '_left_out']
const PORTRAIT_KEYS = ['label', 'episode', 'title', 'image', 'kind', 'crop', 'note', 'title_confirmed']
const PORTRAIT_REQ = ['label', 'episode', 'title', 'image', 'crop']   // `kind` has its own rule
const LEFT_KEYS = ['label', 'episode', 'reason', 'note', 'crop', 'image']
const LEFT_REQ = ['label', 'episode', 'reason', 'note']
const HASH = /^[0-9a-f]{24}$/
const EPISODE = /open\.spotify\.com\/(?:intl-[a-z]+\/)?episode\/([A-Za-z0-9]{22})/

/** The rules, in the order they are reported. */
const RULES: Array<[string, string]> = [
  ['review-missing', 'data/portraits-review.json exists and is readable'],
  ['review-valid', 'the review has the agreed shape (keys, required fields, picture hashes)'],
  ['roster-label', 'every entry is a sage on the roster, with the label the roster has for that id'],
  ['roster-coverage', 'every sage with a Spotify episode is kept or left out under the same episode, the others are no-episode'],
  ['files-for-kept', 'every kept sage has the large, the small and the share-card file'],
  ['no-stray-files', 'no file in public/portraits/ or assets/og/portraits/ lacks a kept sage'],
  ['webp-size', 'large webp at most 40 KB and 384 x 384, small at most 8 KB and 128 x 128'],
  ['og-jpeg', 'share-card jpg at most 30 KB, baseline, 320 x 320'],
  ['total-size', 'public/portraits/ is at most 20 MB in all'],
  ['left-out-clean', 'a sage who is left out has no file and no data entry'],
  ['data-file', 'public/data-portraits.json equals what the review says (ids in order, labels, episodes, w, kind)'],
  ['crops', 'every crop is three integers inside the 640 px picture, at least 160 px'],
  ['reasons', 'every left-out has a reason from the list and a note'],
  ['kinds', 'kind is illustration or photo, and photo only for an id the owner approved'],
  ['photo-crops', 'a left-out photograph (or an uncertain one) has a crop and an image, or says "no crop"'],
  ['title-confirmed', 'a kept sage whose episode title does not name him has title_confirmed'],
  ['portrait-lookup', 'portraitOf is null for a left-out sage and the right portrait for a kept one'],
]

interface Problem { rule: string; detail: string }
type Found = { src: string; srcSm: string; episode: string; kind: string } | null
type Lookup = (id: string) => Found
interface RosterNode { id: string; label: string; spotify_url?: string; era_key?: string }
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Json = any

// ---- the pictures, read by hand ----
function webpInfo(buf: Buffer): { type: string; w: number; h: number } | null {
  if (buf.length < 30 || buf.toString('latin1', 0, 4) !== 'RIFF' || buf.toString('latin1', 8, 12) !== 'WEBP') return null
  const type = buf.toString('latin1', 12, 16)
  if (type === 'VP8 ') {
    if (buf[23] !== 0x9d || buf[24] !== 0x01 || buf[25] !== 0x2a) return null
    return { type, w: buf.readUInt16LE(26) & 0x3fff, h: buf.readUInt16LE(28) & 0x3fff }
  }
  if (type === 'VP8L') {
    if (buf[20] !== 0x2f) return null
    const bits = buf.readUInt32LE(21)
    return { type, w: (bits & 0x3fff) + 1, h: ((bits >>> 14) & 0x3fff) + 1 }
  }
  if (type === 'VP8X') return { type, w: buf.readUIntLE(24, 3) + 1, h: buf.readUIntLE(27, 3) + 1 }
  return null
}

/** The start-of-frame marker of a JPEG: 0xC0 is baseline, 0xC2 progressive. */
function jpegInfo(buf: Buffer): { marker: number; w: number; h: number } | null {
  if (buf.length < 4 || buf[0] !== 0xff || buf[1] !== 0xd8) return null
  let pos = 2
  while (pos + 4 <= buf.length) {
    if (buf[pos] !== 0xff) return null
    const marker = buf[pos + 1]
    if (marker === 0xff) { pos++; continue }
    if (marker === 0x01 || (marker >= 0xd0 && marker <= 0xd8)) { pos += 2; continue }
    if (marker === 0xd9 || marker === 0xda) return null
    if (marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc) {
      if (pos + 9 > buf.length) return null
      return { marker, h: buf.readUInt16BE(pos + 5), w: buf.readUInt16BE(pos + 7) }
    }
    pos += 2 + buf.readUInt16BE(pos + 2)
  }
  return null
}

// ---- does the episode title name the sage? (the heuristic scripts/build_portraits.py uses) ----
const NIKUD = /[֑-ׇ]/g
const QUOTES = /["״׳'’“”‘`]/g
const STOP = new Set('רבי רבנו רבן הרב ר הגאון מרן החכם הרבנית רבינו רבותינו של בן בר בת ה ו את על אל the of and rabbi'.split(' '))
const PREFIX = 'הוולבמכש'
const norm = (s: string) => (s || '').replace(NIKUD, '').replace(QUOTES, '').replace(/[-–—―,:;.!?()[\]\/|·•]/g, ' ').replace(/\s+/g, ' ').trim()
const words = (s: string) => norm(s).split(' ').filter(Boolean)
function variants(tok: string): string[] {
  return tok.length > 3 && PREFIX.includes(tok[0]) ? [tok, tok.slice(1)] : [tok]
}
function nameTokens(label: string): string[] {
  const base = label.split(/\s[–—-]\s/)[0].replace(/\(\d[^)]*\)/g, ' ')
  return words(base).filter(t => !STOP.has(t) && t.length >= 2)
}
function nameInTitle(label: string, title: string): boolean {
  const inTitle = new Set(words(title).flatMap(variants))
  const groups = [label, ...Array.from(label.matchAll(/\(([^)]*)\)/g), m => m[1])]
  return groups.some(g => nameTokens(g).some(tok => variants(tok).some(v => inTitle.has(v))))
}

// ---- the rules, over a root laid out like the repo ----
const LAYOUT = {
  review: 'data/portraits-review.json',
  roster: 'nextjs-app/public/data.json',
  large: 'nextjs-app/public/portraits',
  og: 'nextjs-app/assets/og/portraits',
  data: 'nextjs-app/public/data-portraits.json',
}
const at = (root: string, rel: string) => path.join(root, ...rel.split('/'))
const idOrder = (a: string, b: string) => Number(a) - Number(b) || (a < b ? -1 : a > b ? 1 : 0)
const isObject = (v: unknown): v is Record<string, Json> => !!v && typeof v === 'object' && !Array.isArray(v)

function cropProblem(crop: unknown): string | null {
  if (!Array.isArray(crop) || crop.length !== 3 || !crop.every(v => Number.isInteger(v))) return `not [x, y, size] of three integers (${JSON.stringify(crop)})`
  const [x, y, s] = crop as number[]
  if (x < 0 || y < 0) return `${JSON.stringify(crop)} starts outside the picture`
  if (x + s > PIC || y + s > PIC) return `${JSON.stringify(crop)} reaches outside the ${PIC} px picture`
  if (s < MIN_CROP) return `${JSON.stringify(crop)} is under ${MIN_CROP} px`
  return null
}

function portraitProblems(root: string, lookup: Lookup): Problem[] {
  const out: Problem[] = []
  const add = (rule: string, detail: string) => out.push({ rule, detail })

  const reviewFile = at(root, LAYOUT.review)
  if (!fs.existsSync(reviewFile)) {
    add('review-missing', `${LAYOUT.review} does not exist: run scripts/build_portraits.py after the review is merged`)
    return out
  }
  let review: Json
  try {
    review = JSON.parse(fs.readFileSync(reviewFile, 'utf8'))
  } catch (e) {
    add('review-missing', `${LAYOUT.review} is not JSON: ${(e as Error).message}`)
    return out
  }

  // review shape
  if (!isObject(review)) {
    add('review-valid', 'the review is not an object')
    return out
  }
  for (const k of Object.keys(review)) if (!TOP_KEYS.includes(k)) add('review-valid', `unknown top-level key "${k}"`)
  const portraits: Record<string, Json> = isObject(review.portraits) ? review.portraits : {}
  const left: Record<string, Json> = isObject(review._left_out) ? review._left_out : {}
  if (!isObject(review.portraits) || !isObject(review._left_out)) add('review-valid', '"portraits" and "_left_out" must both be objects')
  const approvedList: unknown = review._approved_photos ?? []
  if (!Array.isArray(approvedList) || !approvedList.every(x => typeof x === 'string' && /^\d+$/.test(x))) add('review-valid', '"_approved_photos" must be a list of id strings')
  const approved = new Set<string>(Array.isArray(approvedList) ? approvedList.filter((x): x is string => typeof x === 'string') : [])

  for (const [id, e] of Object.entries(portraits)) {
    if (!isObject(e)) { add('review-valid', `${id}: portraits entry is not an object`); continue }
    for (const k of Object.keys(e)) if (!PORTRAIT_KEYS.includes(k)) add('review-valid', `${id}: unknown key "${k}" in a portraits entry`)
    for (const k of PORTRAIT_REQ) if (!(k in e)) add('review-valid', `${id}: portraits entry lacks "${k}"`)
    if (!HASH.test(String(e.image ?? ''))) add('review-valid', `${id}: image "${e.image}" is not a 24-hex picture hash`)
    if (!String(e.title ?? '').trim()) add('review-valid', `${id}: the episode title is empty`)
  }
  for (const [id, e] of Object.entries(left)) {
    if (!isObject(e)) { add('review-valid', `${id}: _left_out entry is not an object`); continue }
    for (const k of Object.keys(e)) if (!LEFT_KEYS.includes(k)) add('review-valid', `${id}: unknown key "${k}" in a _left_out entry`)
    for (const k of LEFT_REQ) if (!(k in e)) add('review-valid', `${id}: _left_out entry lacks "${k}"`)
    if ('image' in e && !HASH.test(String(e.image))) add('review-valid', `${id}: image "${e.image}" is not a 24-hex picture hash`)
  }

  // the roster
  const rosterFile = at(root, LAYOUT.roster)
  const roster = new Map<string, RosterNode>()
  for (const n of (JSON.parse(fs.readFileSync(rosterFile, 'utf8')).nodes as RosterNode[])) roster.set(String(n.id), n)
  const episodeOf = (id: string) => EPISODE.exec(roster.get(id)?.spotify_url ?? '')?.[1] ?? null

  for (const [bucket, entries] of [['kept', portraits], ['left out', left]] as const) {
    for (const [id, e] of Object.entries(entries)) {
      const sage = roster.get(id)
      if (!sage) { add('roster-label', `${id} (${bucket}) is not a sage on the roster`); continue }
      if (isObject(e) && e.label !== sage.label) add('roster-label', `${id} (${bucket}): the review says "${e.label}", the roster says "${sage.label}"`)
    }
  }

  // coverage
  for (const id of Object.keys(portraits)) if (id in left) add('roster-coverage', `${id}: in both portraits and _left_out`)
  for (const [id, sage] of roster) {
    const ep = episodeOf(id)
    const decision = portraits[id] ?? left[id]
    if (!decision) { add('roster-coverage', `${id} ("${sage.label}") is neither kept nor left out`); continue }
    if (ep) {
      if (decision.episode !== ep) add('roster-coverage', `${id}: the review says episode "${decision.episode}", his spotify_url says "${ep}"`)
      if (decision.reason === 'no-episode') add('roster-coverage', `${id}: marked no-episode but his spotify_url holds episode ${ep}`)
    } else {
      if (!(id in left) || decision.reason !== 'no-episode') add('roster-coverage', `${id}: has no episode in his spotify_url, so he is left out as no-episode`)
    }
  }

  // reasons, kinds, crops, photographs
  for (const [id, e] of Object.entries(left)) {
    if (!isObject(e)) continue
    if (!REASONS.includes(e.reason)) add('reasons', `${id}: reason "${e.reason}" is not one of ${REASONS.join(' | ')}`)
    if (!String(e.note ?? '').trim()) add('reasons', `${id}: a left-out needs a note`)
    if (e.reason === 'no-episode' && e.episode !== '') add('reasons', `${id}: no-episode, so "episode" must be ""`)
    if (e.reason !== 'no-episode' && e.episode === '') add('reasons', `${id}: an empty episode is only for no-episode`)
    if ('crop' in e) {
      const p = cropProblem(e.crop)
      if (p) add('crops', `${id} (left out): crop ${p}`)
      if (!('image' in e)) add('photo-crops', `${id}: a left-out with a crop needs "image", so a later approval can build it`)
    }
    const note = String(e.note ?? '').toLowerCase()
    if ((e.reason === 'photo' || note.startsWith('uncertain')) && !('crop' in e) && !note.includes('no crop')) {
      add('photo-crops', `${id}: left out as "${e.reason}" with neither a crop nor "no crop" in the note`)
    }
  }
  for (const [id, e] of Object.entries(portraits)) {
    if (!isObject(e)) continue
    if ('crop' in e) {
      const p = cropProblem(e.crop)
      if (p) add('crops', `${id} (kept): crop ${p}`)
    }
    if (!KINDS.includes(e.kind)) add('kinds', `${id}: kind "${e.kind}" is not one of ${KINDS.join(' | ')}`)
    if (e.kind === 'photo' && !approved.has(id)) add('kinds', `${id}: kind "photo" but the owner has not approved this photograph`)
    if (e.kind === 'illustration' && approved.has(id)) add('kinds', `${id}: approved as a photograph, so kind must be "photo", never the illustration caption`)
    if (typeof e.label === 'string' && !nameInTitle(e.label, String(e.title ?? '')) && !String(e.title_confirmed ?? '').trim()) {
      add('title-confirmed', `${id}: the episode title "${e.title}" does not name "${e.label}" and has no title_confirmed`)
    }
  }

  // who is built: every portraits entry, and an approved id left out as photo with a usable crop and image
  const kept = new Map<string, { label: string; episode: string; kind: string }>()
  for (const [id, e] of Object.entries(portraits)) if (isObject(e)) kept.set(id, { label: e.label, episode: e.episode, kind: e.kind })
  for (const id of approved) {
    const e = left[id]
    if (id in portraits) continue
    if (!e) { add('kinds', `${id}: in _approved_photos but neither kept nor left out`); continue }
    if (e.reason === 'photo') {
      if (isObject(e) && !cropProblem(e.crop) && HASH.test(String(e.image ?? ''))) kept.set(id, { label: e.label, episode: e.episode, kind: 'photo' })
      else add('kinds', `${id}: approved as a photograph and left out as "photo", but without a usable crop and image, so he is not built`)
    }
  }

  // files
  const large = at(root, LAYOUT.large)
  const og = at(root, LAYOUT.og)
  const list = (dir: string) => (fs.existsSync(dir) ? fs.readdirSync(dir) : [])
  const largeNames = new Set<string>()
  const ogNames = new Set<string>()
  for (const id of kept.keys()) {
    largeNames.add(`${id}.webp`)
    largeNames.add(`${id}.sm.webp`)
    ogNames.add(`${id}.jpg`)
  }
  for (const [dir, names, label] of [[large, largeNames, LAYOUT.large], [og, ogNames, LAYOUT.og]] as const) {
    for (const n of names) if (!fs.existsSync(path.join(dir, n))) add('files-for-kept', `${label}/${n} is missing`)
    for (const n of list(dir)) if (!names.has(n)) add('no-stray-files', `${label}/${n} belongs to no kept sage`)
  }
  for (const id of kept.keys()) {
    const big = path.join(large, `${id}.webp`)
    const sm = path.join(large, `${id}.sm.webp`)
    const jpg = path.join(og, `${id}.jpg`)
    for (const [file, w, max, label] of [[big, PORTRAIT_SIZE, MAX_LARGE, 'large webp'], [sm, PORTRAIT_SIZE_SM, MAX_SMALL, 'small webp']] as const) {
      if (!fs.existsSync(file)) continue
      const buf = fs.readFileSync(file)
      const info = webpInfo(buf)
      if (!info) add('webp-size', `${id}: the ${label} is not a WebP file`)
      else if (info.w !== w || info.h !== w) add('webp-size', `${id}: the ${label} is ${info.w} x ${info.h}, not ${w} x ${w}`)
      if (buf.length > max) add('webp-size', `${id}: the ${label} is ${buf.length} bytes, over ${max}`)
    }
    if (fs.existsSync(jpg)) {
      const buf = fs.readFileSync(jpg)
      const info = jpegInfo(buf)
      if (!info) add('og-jpeg', `${id}: the share-card file is not a JPEG`)
      else {
        if (info.w !== OG_SIZE || info.h !== OG_SIZE) add('og-jpeg', `${id}: the share-card jpg is ${info.w} x ${info.h}, not ${OG_SIZE} x ${OG_SIZE}`)
        if (info.marker !== 0xc0 && info.marker !== 0xc1) add('og-jpeg', `${id}: the share-card jpg is not baseline (marker 0x${info.marker.toString(16)})`)
      }
      if (buf.length > MAX_OG) add('og-jpeg', `${id}: the share-card jpg is ${buf.length} bytes, over ${MAX_OG}`)
    }
  }
  let total = 0
  for (const n of list(large)) total += fs.statSync(path.join(large, n)).size
  if (total > MAX_TOTAL) add('total-size', `public/portraits/ is ${total} bytes, over ${MAX_TOTAL}`)

  // the data file
  const dataFile = at(root, LAYOUT.data)
  let data: Record<string, Json> = {}
  if (!fs.existsSync(dataFile)) add('data-file', `${LAYOUT.data} does not exist`)
  else {
    try { data = JSON.parse(fs.readFileSync(dataFile, 'utf8')) } catch (e) { add('data-file', `${LAYOUT.data} is not JSON: ${(e as Error).message}`) }
  }
  const dataIds = Object.keys(data)
  // a JS object lists integer-like keys in ascending order whatever the file says, so read the order from the text
  const textOrder = fs.existsSync(dataFile) ? Array.from(fs.readFileSync(dataFile, 'utf8').matchAll(/^ "([^"]+)": \{/gm), m => m[1]) : []
  if (textOrder.some((id, i) => i > 0 && idOrder(textOrder[i - 1], id) > 0)) add('data-file', 'the ids are not in ascending order')
  for (const [id, k] of kept) {
    const d = data[id]
    if (!d) { add('data-file', `${id}: kept but has no entry`); continue }
    if (Object.keys(d).sort().join() !== 'episode,kind,label,w') add('data-file', `${id}: entry keys are ${Object.keys(d).join(',')}, not label, episode, w, kind`)
    if (d.label !== k.label) add('data-file', `${id}: label "${d.label}", the review says "${k.label}"`)
    if (d.episode !== k.episode) add('data-file', `${id}: episode "${d.episode}", the review says "${k.episode}"`)
    if (d.kind !== k.kind) add('data-file', `${id}: kind "${d.kind}", the review says "${k.kind}"`)
    if (d.w !== PORTRAIT_SIZE) add('data-file', `${id}: w ${d.w}, not ${PORTRAIT_SIZE}`)
  }
  for (const id of dataIds) if (!kept.has(id)) add('data-file', `${id}: has an entry but is not kept`)

  // a sage who is left out has nothing (an approved photograph left out with a crop and an image is built, so he is kept)
  for (const id of Object.keys(left)) {
    if (kept.has(id)) continue
    for (const f of [path.join(large, `${id}.webp`), path.join(large, `${id}.sm.webp`), path.join(og, `${id}.jpg`)]) {
      if (fs.existsSync(f)) add('left-out-clean', `${id}: left out, but ${path.basename(f)} exists`)
    }
    if (id in data) add('left-out-clean', `${id}: left out, but the data file has an entry`)
  }

  // what a component sees
  for (const [id, k] of kept) {
    const p = lookup(id)
    if (!p) { add('portrait-lookup', `${id}: kept, but portraitOf gives null`); continue }
    if (p.src !== `/portraits/${id}.webp` || p.srcSm !== `/portraits/${id}.sm.webp`) add('portrait-lookup', `${id}: wrong paths ${p.src} ${p.srcSm}`)
    if (p.episode !== k.episode) add('portrait-lookup', `${id}: episode "${p.episode}", the review says "${k.episode}"`)
    if (p.kind !== k.kind) add('portrait-lookup', `${id}: kind "${p.kind}", the review says "${k.kind}"`)
  }
  for (const id of Object.keys(left)) if (!kept.has(id) && lookup(id)) add('portrait-lookup', `${id}: left out, but portraitOf gives a portrait`)

  return out
}

// ======================================================================
console.log('\nthe picture readers')

const REAL_ROOT = path.resolve(__dirname, '..', '..')
const realEntries = portraitEntries()

test('the data file is not empty', () => {
  assert.ok(realEntries.length > 0, 'public/data-portraits.json holds no entry')
})

const sample = realEntries.find(([, e]) => e.kind === 'illustration') ?? realEntries[0]
const samplePhoto = realEntries.find(([, e]) => e.kind === 'photo') ?? sample
const realFile = (dir: string, name: string) => path.join(at(REAL_ROOT, dir), name)

test('a real large, small and share-card file read as 384, 128 and 320 px', () => {
  const [id] = sample
  const big = webpInfo(fs.readFileSync(realFile(LAYOUT.large, `${id}.webp`)))
  const sm = webpInfo(fs.readFileSync(realFile(LAYOUT.large, `${id}.sm.webp`)))
  const jpg = jpegInfo(fs.readFileSync(realFile(LAYOUT.og, `${id}.jpg`)))
  assert.deepEqual([big?.w, big?.h], [PORTRAIT_SIZE, PORTRAIT_SIZE])
  assert.deepEqual([sm?.w, sm?.h], [PORTRAIT_SIZE_SM, PORTRAIT_SIZE_SM])
  assert.deepEqual([jpg?.w, jpg?.h, jpg?.marker], [OG_SIZE, OG_SIZE, 0xc0])
})

test('a file that is not a picture reads as null', () => {
  assert.equal(webpInfo(Buffer.from('not a picture at all, just text bytes ...')), null)
  assert.equal(jpegInfo(Buffer.from('not a picture at all')), null)
})

// ---- fake pictures with the right headers, for the broken copies ----
function fakeWebp(w: number, h: number, bytes: number): Buffer {
  const b = Buffer.alloc(Math.max(bytes, 30))
  b.write('RIFF', 0, 'latin1')
  b.writeUInt32LE(b.length - 8, 4)
  b.write('WEBP', 8, 'latin1')
  b.write('VP8L', 12, 'latin1')
  b.writeUInt32LE(b.length - 20, 16)
  b[20] = 0x2f
  b.writeUInt32LE(((w - 1) | ((h - 1) << 14)) >>> 0, 21)
  return b
}
function fakeJpeg(w: number, h: number, bytes: number, marker = 0xc0): Buffer {
  const head = Buffer.from([0xff, 0xd8, 0xff, marker, 0x00, 0x0b, 0x08, h >> 8, h & 255, w >> 8, w & 255, 0x01, 0x01, 0x11, 0x00])
  const pad = Buffer.alloc(Math.max(bytes - head.length - 2, 0))
  return Buffer.concat([head, pad, Buffer.from([0xff, 0xd9])])
}

test('the fake pictures read back as what they say', () => {
  assert.deepEqual(webpInfo(fakeWebp(384, 384, 100)), { type: 'VP8L', w: 384, h: 384 })
  assert.deepEqual(webpInfo(fakeWebp(128, 130, 100)), { type: 'VP8L', w: 128, h: 130 })
  assert.deepEqual(jpegInfo(fakeJpeg(320, 320, 100)), { marker: 0xc0, w: 320, h: 320 })
  assert.equal(jpegInfo(fakeJpeg(300, 310, 100, 0xc2))?.marker, 0xc2)
})

